// Generates the markdown documents of handoff/INFORMATION_EDGE_V6 from results/v6_results.json.
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const HERE = dirname(fileURLToPath(import.meta.url)); const REPO = join(HERE, '..', '..', '..'); const ROOT = join(REPO, 'research', 'information_edge_v6'); const R = JSON.parse(readFileSync(join(ROOT, 'results', 'v6_results.json'), 'utf8')); const DEFN = R.finalist_definitions; const OUT = join(REPO, 'handoff', 'INFORMATION_EDGE_V6'); mkdirSync(OUT, { recursive: true });
const f = (x, d = 3) => (x == null ? '—' : typeof x === 'number' ? (Number.isInteger(x) ? String(x) : x.toFixed(d)) : String(x)); const ci = (c) => (c ? `[${f(c[0])}, ${f(c[1])}]` : '—'); const pc = (x) => (x == null ? '—' : `${(x * 100).toFixed(1)} %`); const S2 = ['DEV', 'HOLD']; const POPS = ['CONTROL', 'S3']; const W = (name, md) => writeFileSync(join(OUT, name), md);
const CANDS = DEFN.candidates; const DEC = R.decisions; const HC = R.HOLD.candidates.CONTROL.CONTROL; const DC = R.DEV.candidates.CONTROL.CONTROL; const BEST = DEC.best_candidate; const HB = R.HOLD.candidates.CONTROL[BEST];
const FAMDOC = { A_HTF: 'HTF_STRUCTURE.md', B_SESSION: 'SESSION_CONTEXT.md', C_VOL: 'VOLATILITY_CONTEXT.md', D_REGIME: 'REGIME_CONTEXT.md', E_MOM: 'MOMENTUM_CONTEXT.md', F_RANGE_POS: 'RANGE_CONTEXT.md', G_LOCATION: 'STRUCTURAL_LOCATION.md', H_SWEEP: 'LIQUIDITY_CONTEXT.md', I_NEWS: 'NEWS_MACRO_CONTEXT.md', J_XTF: 'CROSS_TIMEFRAME_CONTEXT.md', K_VOLUME: 'VOLUME_ACTIVITY.md', L_SHOCK: 'SHOCK_STATE.md' };
const FAMSUB = { A_HTF: ['A_HTF', 'A2_HTF_TREND'], B_SESSION: ['B_SESSION', 'B2_TIME'], C_VOL: ['C_VOL', 'C2_RANGE_STATE'], D_REGIME: ['D_REGIME'], E_MOM: ['E_MOM', 'E2_MOM_FLAGS'], F_RANGE_POS: ['F_RANGE_POS', 'F2_RANGE_FLAGS'], G_LOCATION: ['G_LOCATION'], H_SWEEP: ['H_SWEEP', 'H2_EQUAL'], I_NEWS: ['I_NEWS'], J_XTF: ['J_XTF'], K_VOLUME: ['K_VOLUME'], L_SHOCK: ['L_SHOCK'] };
const FAMTITLE = { A_HTF: 'A. HIGHER-TIMEFRAME STRUCTURE', B_SESSION: 'B. SESSION / TIME CONTEXT', C_VOL: 'C. VOLATILITY STATE', D_REGIME: 'D. MARKET REGIME', E_MOM: 'E. MOMENTUM CONTEXT', F_RANGE_POS: 'F. RANGE / COMPRESSION', G_LOCATION: 'G. STRUCTURAL LOCATION', H_SWEEP: 'H. LIQUIDITY / SWEEP', I_NEWS: 'I. NEWS / MACRO STATE', J_XTF: 'J. CROSS-TIMEFRAME AGREEMENT', K_VOLUME: 'K. VOLUME / ACTIVITY (MT5 tick volume proxy)', L_SHOCK: 'L. SHOCK STATE' };
const FIXEDOF = { A_HTF: 'C1 V6-HTF', J_XTF: 'C2 V6-AGREE', E_MOM: 'C3 V6-MOM', G_LOCATION: 'C4 V6-LOC', L_SHOCK: 'C5 V6-SAFETY', I_NEWS: 'C5 V6-SAFETY' };
const STH = '| Population | Split | State | N | Share | Win | Avg win / loss (R) | Exp (R) | PF | Wrong-direction | Bad-entry | MFE open / MAE (R) | 95 % CI |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const stRows = (fam) => POPS.flatMap((pop) => S2.flatMap((S) => { const T = R[S].tables[pop]; const states = T.families[fam]; return [`| ${pop} | ${S} | **base (all signals)** | ${T.base.n} | 100 % | ${pc(T.base.win_rate)} | ${f(T.base.avg_win_r, 2)} / ${f(T.base.avg_loss_r, 2)} | ${f(T.base.expectancy_r)} | ${f(T.base.pf, 2)} | ${pc(T.base.wrong_direction_rate)} | ${pc(T.base.bad_entry_rate)} | ${f(T.base.mfe_open_r, 2)} / ${f(T.base.mae_r, 2)} | ${ci(T.base.ci95_r)} |`, ...Object.entries(states).map(([k, v]) => `| ${pop} | ${S} | ${k} | ${v.n}${v.n < 30 ? ' (INSUFFICIENT)' : ''} | ${pc(v.n / T.base.n)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${f(v.mfe_open_r, 2)} / ${f(v.mae_r, 2)} | ${ci(v.ci95_r)} |`)]; })).join('\n');
const INCH = '| Split | Population | Filter | Trades | WAIT share | Exp (R) | Δ exp vs CONTROL | PF | DD (R) | Wrong-direction (trade) | Δ WD | Event wrong-direction | Bad-entry | Move capture | Incremental value |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const incRow = (S, pop, k, v) => `| ${S} | ${pop} | ${k} | ${v.n} | ${pc(v.wait_share)} | ${f(v.expectancy_r)} | ${f(v.improvement_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${pc(v.wrong_direction_rate)} | ${f(v.wd_change)} | ${pc(v.event_wd)} | ${pc(v.bad_entry_rate)} | ${pc(v.capture)} | ${v.incremental ? 'YES' : 'no'} |`;
const CANDH = '| Candidate | Signals in → kept (WAIT) | Trades | Win | Avg win / loss (R) | Exp (R) | PF | DD (R) | Trade 95 % CI | Block 95 % CI | Stress | Drift | Quarters > 0 | Wrong-direction (trade / events) | Bad-entry | Capture | Blocked events |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const candRow = (v, name) => (v.n ? `| ${name} | ${v.signals_in} → ${v.signals_kept} (${pc(v.wait_share)}) | ${v.n} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${ci(v.block_ci95_r)} | ${f(v.stress?.expectancy_r)} | ${f(v.drift?.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${pc(v.wrong_direction_rate)} / ${pc(v.move_capture.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.blocked_events_share)} |` : `| ${name} | ${v.signals_in} → ${v.signals_kept} (${pc(v.wait_share)}) | 0 | — | — | — | — | — | — | — | — | — | — | — | — | 0 | — |`);
const candTable = (pop, S) => `${CANDH}\n${candRow(R[S].candidates[pop].CONTROL, 'CONTROL (no V6 layer)')}\n${CANDS.map((k) => candRow(R[S].candidates[pop][k], k)).join('\n')}`;

// ---------- control / provenance ----------
W('V6_CONTROL_BASELINE.md', readFileSync(join(ROOT, 'V6_CONTROL_BASELINE.md'), 'utf8') + `\n## Reproduction (asserted by the study)\n| Split | Population | n | Exp (R) | PF | DD (R) | Capture | Event wrong-direction |\n|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => POPS.map((pop) => { const v = R[S].candidates[pop].CONTROL; return `| ${S} | ${pop} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 2)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.move_capture.wrong_direction_rate)} |`; })).join('\n')}\n\ncontrol_reproduces_v5_dev = ${R.meta.controls.control_reproduces_v5_dev}; control_reproduces_v5_hold = ${R.meta.controls.control_reproduces_v5_hold}.\n`);
for (const fn of ['V6_PREREGISTRATION.md', 'V6_PREREGISTRATION.sha256', 'V6_CONTROL_BASELINE.sha256']) copyFileSync(join(ROOT, fn), join(OUT, fn));
W('DATA_PROVENANCE.md', `# DATA PROVENANCE\n\n| Input | Source | Size | Hash reference |\n|---|---|---|---|\n| 5m bars (OHLC, MT5 tick volume, spread points) | handoff/edge_discovery_lab/data/XAUUSDm_bars.json (2025-05-05 → 2026-09-30) | 99,990 bars | results/control_inputs.sha256 |\n| Replay rows (5m regime/structure, 15m bias/regime/structure, 30m regime/structure, 1H regime/structure, 4H regime, session, sweep) | handoff/edge_discovery_lab/data/lab_rows.jsonl | 99,381 in-range rows | results/control_inputs.sha256 |\n| CONTROL entries with production geometry | research/entry_architecture_v2/results/candidates.jsonl | ${R.meta.populations.CONTROL.all} signals (DEV ${R.meta.populations.CONTROL.dev} / HOLD ${R.meta.populations.CONTROL.hold}) | results/control_inputs.sha256 |\n| V4 S3 entries (first structure break) | regenerated verbatim via research/trade_economics_v5/scripts/v4_populations.mjs from research/entry_core_v4/configs/finalists.json (sha ${R.meta.v4_finalists_sha256.slice(0, 16)}…) | ${R.meta.populations.S3.all} signals | results/control_inputs.sha256 |\n| Official USD macro release timestamps (FOMC, CPI, NFP, PPI, PCE, JOLTS, GDP advance) | validation/v5_news_edge/events_usd_official.json (primary sources: Federal Reserve, BLS, BEA; DST-checked) | ${R.meta.controls.news_events_in_range} releases inside the bar range | results/control_inputs.sha256 (sha ${R.meta.news_file_sha256.slice(0, 16)}…) |\n| Exit simulator / re-entry guard | research/trade_economics_v5/scripts/exitPolicies.mjs; src/engine/capitalHarvest/positionManager.js canReenter (pure, unwired) | — | repo HEAD |\n\nSplit: DEV ${R.meta.split.dev.join(' → ')} (${R.meta.sessions_dev ?? 205} sessions), HOLDOUT ${R.meta.split.hold.join(' → ')} (${R.meta.sessions_hold ?? 232} sessions). Costs ${JSON.stringify(R.meta.costs)}. Volume note: ${R.meta.tick_volume_note}. No feed was invented: every family uses data already present in the environment. News V2 (production) remains authoritative; the research news state is a diagnostic label from scheduled timestamps.\n`);

// ---------- family documents ----------
const FAMREAD = {
  A_HTF: () => { const h = R.HOLD.tables.CONTROL.families.A_HTF, d = R.DEV.tables.CONTROL.families.A_HTF; return `HTF agreement does not reduce wrong-direction trades: CONTROL wrong-direction is ${pc(d.HTF_ALIGNED.wrong_direction_rate)} / ${pc(d.HTF_CONFLICTING.wrong_direction_rate)} (aligned / conflicting) on DEV and ${pc(h.HTF_ALIGNED.wrong_direction_rate)} / ${pc(h.HTF_CONFLICTING.wrong_direction_rate)} on HOLD — identical within noise. Economics are, if anything, inverted: HTF_CONFLICTING is the least negative state on HOLD (${f(h.HTF_CONFLICTING.expectancy_r)} R vs aligned ${f(h.HTF_ALIGNED.expectancy_r)} R) for CONTROL and the best state for S3 on HOLD (+0.033 R), exactly as V1's gate ablation (1H veto SUPPRESSES_VALUE) and V4's HTF_CONTEXT found. Excluding conflicting trades (C1) changes expectancy by ${f(R.incremental.HOLD.CONTROL['C1 V6-HTF'].improvement_r)} R on HOLD and ${f(R.incremental.DEV.CONTROL['C1 V6-HTF'].improvement_r)} R on DEV with wrong direction unchanged. "Trend-with on both 30m and 1H" is worse than "no HTF trend" on both splits. Verdict: HTF structure carries no directional information for these entries; alignment must not be made a block.`; },
  B_SESSION: () => { const h = R.HOLD.tables.CONTROL.families.B2_TIME, d = R.DEV.tables.CONTROL.families.B2_TIME; return `Session economics do not persist: NEW_YORK was the only positive session on DEV (+0.010 R) and is −0.066 R on HOLD; the London/NY OVERLAP window was the strongest state in the whole study on DEV (${f(d.OVERLAP.expectancy_r)} R, n ${d.OVERLAP.n}, wrong direction ${pc(d.OVERLAP.wrong_direction_rate)}) and is ${f(h.OVERLAP.expectancy_r)} R on HOLD; the US data window flipped from +0.114 to −0.163 R. Session opens are negative on both splits (−0.145 / −0.207 R) but with higher spread exposure rather than worse direction. For S3 the ASIA session is the best state on HOLD (+0.078 R) and was not on DEV. Wrong-direction rates are 29–34 % in every session. Verdict: no session filter has robust economic value; none is adopted.`; },
  C_VOL: () => { const h = R.HOLD.tables.CONTROL.families, d = R.DEV.tables.CONTROL.families; return `Volatility state does not separate direction: wrong-direction is 29–33 % in LOW, NORMAL and HIGH ATR percentile on both splits. HIGH volatility is the least negative state on both splits (DEV ${f(d.C_VOL.HIGH.expectancy_r)}, HOLD ${f(h.C_VOL.HIGH.expectancy_r)} R) and LOW the worst (${f(d.C_VOL.LOW.expectancy_r)} / ${f(h.C_VOL.LOW.expectancy_r)} R), consistent with wider structural stops in high ATR (V5), not with better direction. Range EXPANSION is the only volatility sub-state positive on HOLD (${f(h.C2_RANGE_STATE.EXPANSION.expectancy_r)} R, wrong direction ${pc(h.C2_RANGE_STATE.EXPANSION.wrong_direction_rate)}) and it was ${f(d.C2_RANGE_STATE.EXPANSION.expectancy_r)} R on DEV. SHOCK (L) is addressed separately. Verdict: ALLOW everywhere; no RESTRICT/BLOCK state is supported by direction or economics; volatility is not used to raise frequency.`; },
  D_REGIME: () => { const h = R.HOLD.tables.CONTROL.families.D_REGIME, d = R.DEV.tables.CONTROL.families.D_REGIME; return `The existing regime engine is not directionally predictive: trading WITH the 5m trend regime is ${f(d.TREND_WITH.expectancy_r)} R (DEV) / ${f(h.TREND_WITH.expectancy_r)} R (HOLD) with wrong direction ${pc(d.TREND_WITH.wrong_direction_rate)} / ${pc(h.TREND_WITH.wrong_direction_rate)}; trading AGAINST it is ${f(d.TREND_AGAINST.expectancy_r)} R / ${f(h.TREND_AGAINST.expectancy_r)} R on 112 / 121 trades — a sign flip. RANGE is −0.309 R on DEV and +0.064 R on HOLD; TRANSITION is the worst state on both splits (−0.104 / −0.213 R) but with an ordinary wrong-direction rate. This repeats V3 (REGIME_DIRECTION_MATRIX: zero ROBUST cells) and V4 (REGIME_CONTEXT). Verdict: documented and NOT used as a primary directional filter.`; },
  E_MOM: () => { const h = R.HOLD.tables.CONTROL.families, d = R.DEV.tables.CONTROL.families; return `Momentum is the only family whose fixed rule lowered wrong-direction on DEV (${pc(d.E_MOM.SUPPORTIVE.wrong_direction_rate)} supportive vs ${pc(d.E_MOM.OPPOSING.wrong_direction_rate)} opposing) and the effect is ${pc(h.E_MOM.SUPPORTIVE.wrong_direction_rate)} vs ${pc(h.E_MOM.OPPOSING.wrong_direction_rate)} on HOLD — about one to three points. Excluding opposing momentum (C3) is the best candidate on HOLD by expectancy (${f(R.HOLD.candidates.CONTROL['C3 V6-MOM'].expectancy_r)} R vs CONTROL ${f(HC.expectancy_r)} R) and WORSE than CONTROL on DEV (${f(R.DEV.candidates.CONTROL['C3 V6-MOM'].expectancy_r)} R vs ${f(DC.expectancy_r)} R); its trade-level wrong-direction on HOLD is ${pc(R.HOLD.candidates.CONTROL['C3 V6-MOM'].wrong_direction_rate)} vs ${pc(HC.wrong_direction_rate)} — not lower. EXHAUSTION (|mom12| ≥ 2 ATR against acceleration) was the worst flag on DEV (${f(d.E2_MOM_FLAGS.EXHAUSTION.expectancy_r)} R) and the best on HOLD (${f(h.E2_MOM_FLAGS.EXHAUSTION.expectancy_r)} R); PERSISTENT runs are negative on both. High momentum does not equal BUY/SELL; continuation and acceleration do not separate from exhaustion out of sample. Verdict: momentum does not improve directional accuracy at a usable magnitude.`; },
  F_RANGE_POS: () => { const h = R.HOLD.tables.CONTROL.families, d = R.DEV.tables.CONTROL.families; return `Position inside the 24-bar range: entries at the range EDGE (chasing toward the extreme in the trade direction, ${pc(h.F_RANGE_POS.EDGE.n / R.HOLD.tables.CONTROL.base.n)} of CONTROL) are −0.12 / −0.07 R; MID is the least negative on both splits (${f(d.F_RANGE_POS.MID.expectancy_r)} / ${f(h.F_RANGE_POS.MID.expectancy_r)} R); INSIDE_LOW is rare (3–4 %) and flips sign. POST_BREAK was the only positive flag on DEV (${f(d.F2_RANGE_FLAGS.POST_BREAK.expectancy_r)} R) and is ${f(h.F2_RANGE_FLAGS.POST_BREAK.expectancy_r)} R on HOLD; POST_RECLAIM was ${f(d.F2_RANGE_FLAGS.POST_RECLAIM.expectancy_r)} R on DEV and is the best flag on HOLD (${f(h.F2_RANGE_FLAGS.POST_RECLAIM.expectancy_r)} R, wrong direction ${pc(h.F2_RANGE_FLAGS.POST_RECLAIM.wrong_direction_rate)}). Wrong-direction differences across range states are 2–6 points and do not repeat. Verdict: inside-range / edge / post-break / post-reclaim do not have stable economics; no range filter is adopted.`; },
  G_LOCATION: () => { const h = R.HOLD.tables.CONTROL.families.G_LOCATION, d = R.DEV.tables.CONTROL.families.G_LOCATION; return `Deterministic location (opposing-swing distance ÷ structural risk) is INVERTED on both splits: GOOD location (target unobstructed by the nearest opposing swing, ≥ 1.7 × risk) is ${f(d.GOOD.expectancy_r)} R (DEV) / ${f(h.GOOD.expectancy_r)} R (HOLD); BAD location (opposing swing closer than 1 × risk) is ${f(d.BAD.expectancy_r)} / ${f(h.BAD.expectancy_r)} R and is ${pc(h.BAD.n / R.HOLD.tables.CONTROL.base.n)} of all production entries. Wrong-direction rates are equal (${pc(h.GOOD.wrong_direction_rate)} vs ${pc(h.BAD.wrong_direction_rate)}). Requiring non-BAD location (C4) waits on 83 % of signals, captures ${pc(R.HOLD.candidates.CONTROL['C4 V6-LOC'].move_capture.capture_rate)} of moves and loses ${f(R.HOLD.candidates.CONTROL['C4 V6-LOC'].expectancy_r)} R. The mechanism is V5's: production's objective TP2 sits at the nearest structural objective, so a near opposing swing means a NEAR, reachable target. For the S3 population the feature is degenerate (the broken swing is behind price → always BAD). Verdict: geometry "good location" as defined does not improve direction and worsens economics; the entry-location gate is not adopted.`; },
  H_SWEEP: () => { const h = R.HOLD.tables.CONTROL.families, d = R.DEV.tables.CONTROL.families; return `A recent production sweep AGAINST the trade (price swept the swing in the opposite direction within 6 bars) is negative on both splits (${f(d.H_SWEEP.AGAINST.expectancy_r)} / ${f(h.H_SWEEP.AGAINST.expectancy_r)} R) with the highest wrong-direction rate of the family on HOLD (${pc(h.H_SWEEP.AGAINST.wrong_direction_rate)}) — the most consistent liquidity signal in the study — yet a sweep IN FAVOUR is also negative on both splits (${f(d.H_SWEEP.IN_FAVOUR.expectancy_r)} / ${f(h.H_SWEEP.IN_FAVOUR.expectancy_r)} R) and NONE is best. Equal highs/lows: no difference on HOLD, worse on DEV. The DEV-derived rule did not qualify the family (NONE fails the wrong-direction condition on DEV by 0.3 points). Excluding sweep-against would remove ${pc(h.H_SWEEP.AGAINST.n / R.HOLD.tables.CONTROL.base.n)} of signals for an independent-signal gain of ≈ 0.06 R; it is reported as the one liquidity observation worth a pre-registered forward test, not adopted. Verdict: liquidity concepts are not predictive of direction here; sweep-reclaim as a setup was already negative in V2/V4.`; },
  I_NEWS: () => { const h = R.HOLD.tables.CONTROL.families.I_NEWS, d = R.DEV.tables.CONTROL.families.I_NEWS; return `Only ${pc((h.PRE_NEWS.n + h.POST_NEWS.n) / R.HOLD.tables.CONTROL.base.n)} of production signals fall within 60 min of an official USD release (${R.meta.controls.news_events_in_range} releases in range). Those few are POSITIVE on both splits (PRE_NEWS ${f(d.PRE_NEWS.expectancy_r)} R n ${d.PRE_NEWS.n} DEV, ${f(h.PRE_NEWS.expectancy_r)} R n ${h.PRE_NEWS.n} HOLD; POST_NEWS ${f(d.POST_NEWS.expectancy_r)} / ${f(h.POST_NEWS.expectancy_r)} R) with lower wrong-direction (${pc(h.PRE_NEWS.wrong_direction_rate)}) — a sample of ~110 trades, mostly directional continuation into/after the release, and exactly the window production News V2 blocks for safety reasons (slippage, spread, gaps that the replay does not model). Excluding them (I-fixed, inside C5) therefore WORSENS research economics (C5 HOLD ${f(R.HOLD.candidates.CONTROL['C5 V6-SAFETY'].expectancy_r)} R). Verdict: news state is a safety variable, not a directional one; News V2 is not weakened; the positive pre-news cell is reported, not actionable.`; },
  J_XTF: () => { const h = R.HOLD.tables.CONTROL.families.J_XTF, d = R.DEV.tables.CONTROL.families.J_XTF; return `Cross-timeframe agreement (5m, 15m, 30m, 1H structure): FULL agreement is ${f(d.FULL.expectancy_r)} R (DEV) / ${f(h.FULL.expectancy_r)} R (HOLD), PARTIAL ${f(d.PARTIAL.expectancy_r)} / ${f(h.PARTIAL.expectancy_r)} R, CONFLICT ${f(d.CONFLICT.expectancy_r)} / ${f(h.CONFLICT.expectancy_r)} R; wrong-direction ${pc(h.FULL.wrong_direction_rate)} / ${pc(h.PARTIAL.wrong_direction_rate)} / ${pc(h.CONFLICT.wrong_direction_rate)} on HOLD. CONFLICT is consistently the worst state (6–8 % of signals) but excluding it (C2 = V6-SIMPLE) adds only ${f(R.incremental.DEV.CONTROL['C2 V6-AGREE'].improvement_r)} R (DEV) / ${f(R.incremental.HOLD.CONTROL['C2 V6-AGREE'].improvement_r)} R (HOLD) and does not lower wrong-direction; requiring FULL agreement (neighbour agree=3/4) is worse than the centre. For S3, CONFLICT is the BEST state on HOLD (+0.059 R). Agreement does not improve directional accuracy, expectancy, PF or drawdown materially; it is redundant with HTF structure (phi 0.29) and 5m structure is already in the entry. Verdict: not adopted.`; },
  K_VOLUME: () => { const h = R.HOLD.tables.CONTROL.families.K_VOLUME, d = R.DEV.tables.CONTROL.families.K_VOLUME; return `The volume field is MT5 tick volume of a CFD (number of price updates), not exchange volume — a broker-activity proxy. HIGH relative activity (> 1.5 × the trailing 48-bar mean) is the one state positive on both splits (${f(d.HIGH.expectancy_r)} R DEV, ${f(h.HIGH.expectancy_r)} R HOLD) with lower wrong-direction on both (${pc(d.HIGH.wrong_direction_rate)} / ${pc(h.HIGH.wrong_direction_rate)} vs base ${pc(R.DEV.tables.CONTROL.base.wrong_direction_rate)} / ${pc(R.HOLD.tables.CONTROL.base.wrong_direction_rate)}); it is 18–19 % of signals, the HOLD effect is a fifth of the DEV effect, and its phi with every other family is < 0.1 (independent). It did not enter any candidate because the only candidate that uses DEV-derived states (V6-COMPOSITE) intersects to zero, and no fixed rule was pre-registered for volume. Verdict: tick activity shows a small, decaying, independent association with better outcomes; not enough for a rule, worth a pre-registered single-family forward test.`; },
  L_SHOCK: () => { const h = R.HOLD.tables.CONTROL.families.L_SHOCK, d = R.DEV.tables.CONTROL.families.L_SHOCK; return `SHOCK (3-ATR bar within 3 bars, ATR ratio ≥ 1.5, or abnormal spread) covers ${pc(h.SHOCK.n / R.HOLD.tables.CONTROL.base.n)} of signals. It was the LESS negative state on DEV (${f(d.SHOCK.expectancy_r)} vs ${f(d.NORMAL.expectancy_r)} R) and the more negative on HOLD (${f(h.SHOCK.expectancy_r)} vs ${f(h.NORMAL.expectancy_r)} R), with LOWER wrong-direction in both (${pc(d.SHOCK.wrong_direction_rate)} / ${pc(h.SHOCK.wrong_direction_rate)}). Blocking shock (inside C5) changes HOLD expectancy by ${f(R.incremental.HOLD.CONTROL['C5 V6-SAFETY'].improvement_r)} R. The replay cannot price what shock really costs live (spread blow-out, requotes, gaps); production already has the News V2 and spread/drift guards for that. Verdict: shock is a safety WAIT only; it carries no directional information and must never be a trigger.`; },
};
for (const [fam, file] of Object.entries(FAMDOC)) { const subs = FAMSUB[fam]; let md = `# ${FAMTITLE[fam]}\n\nFrozen definitions: V6_PREREGISTRATION.md §5. Statistics on the frozen entry streams under the control exit (independent signals); WRONG_DIRECTION = open-path MFE < 0.5 R and stopped; BAD_ENTRY = never reached +1 R before invalidation.\n`; for (const sub of subs) md += `\n## ${sub}\n${STH}\n${stRows(sub)}\n`; const fx = FIXEDOF[fam]; if (fx) md += `\n## CONTROL vs CONTROL + family (fixed rule ${fx}; sequential one-position)\n${INCH}\n${S2.flatMap((S) => POPS.map((pop) => incRow(S, pop, fx, R.incremental[S][pop][fx]))).join('\n')}\n`; md += `\n## Reading\n${FAMREAD[fam]()}\n`; W(file, md); }

// ---------- direction / conflict / eligibility ----------
W('DIRECTIONAL_BIAS.md', `# DIRECTIONAL BIAS ENGINE (C6 V6-DIR: BUY/SELL eligible only if at least one of 30m/1H structure agrees and none opposes, momentum not opposing, location not BAD; otherwise WAIT — explicit evidence relations, no composite score)\n\n${S2.map((S) => `## ${S}\n${candTable('CONTROL', S)}\n`).join('\n')}\n## Eligibility outcome on CONTROL signals (HOLD)\nBUY_ALLOWED / SELL_ALLOWED under the engine = the side of the production signal when the engine passes; NEITHER = WAIT. WAIT share ${pc(R.HOLD.candidates.CONTROL['C6 V6-DIR'].wait_share)} of signals (${R.HOLD.candidates.CONTROL['C6 V6-DIR'].signals_kept} kept of ${R.HOLD.candidates.CONTROL['C6 V6-DIR'].signals_in}); the kept trades lose ${f(R.HOLD.candidates.CONTROL['C6 V6-DIR'].expectancy_r)} R (PF ${f(R.HOLD.candidates.CONTROL['C6 V6-DIR'].pf, 2)}) with wrong-direction ${pc(R.HOLD.candidates.CONTROL['C6 V6-DIR'].wrong_direction_rate)} vs CONTROL ${pc(HC.wrong_direction_rate)}; on DEV ${f(R.DEV.candidates.CONTROL['C6 V6-DIR'].expectancy_r)} R on 144 trades. The engine captures ${pc(R.HOLD.candidates.CONTROL['C6 V6-DIR'].move_capture.capture_rate)} of large moves (CONTROL ${pc(HC.move_capture.capture_rate)}).\n\n## Reading\nThe conceptual rule "HTF BUY + 5m BUY + structure supportive + momentum supportive = BUY ELIGIBLE" was validated and rejected: the trades it authorises are wrong-direction as often as the trades it refuses (${pc(R.HOLD.candidates.CONTROL['C6 V6-DIR'].wrong_direction_rate)} vs ${pc(HC.wrong_direction_rate)}), and they lose more per trade. The binding component is location (83 % WAIT on its own), which is inverted (STRUCTURAL_LOCATION.md); without it the engine is C1 ∩ C3, which is ≈ CONTROL. Direction-eligibility layers built from HTF structure, momentum and location do not change which trades are wrong.\n`);
W('CONFLICT_ENGINE.md', `# CONFLICT ENGINE (explicit conflicts → WAIT; economics of conflict vs non-conflict trades, control exit, independent signals)\n\n| Conflict type | Split | Conflict state N / exp (R) / wrong-direction | Non-conflict N / exp / wrong-direction | Removing conflicts (sequential): Δ exp / Δ WD |\n|---|---|---|---|---|\n${S2.flatMap((S) => { const T = R[S].tables.CONTROL.families, I = R.incremental[S].CONTROL; const nonc = (fam, k) => { const o = Object.entries(T[fam]).filter(([kk]) => kk !== k); const n = o.reduce((a, [, v]) => a + v.n, 0); return { n, exp: o.reduce((a, [, v]) => a + v.n * (v.expectancy_r ?? 0), 0) / Math.max(1, n), wd: o.reduce((a, [, v]) => a + v.n * (v.wrong_direction_rate ?? 0), 0) / Math.max(1, n) }; }; const row = (label, fam, k, inc) => { const c = T[fam][k], nc = nonc(fam, k); return `| ${label} | ${S} | ${c.n} / ${f(c.expectancy_r)} / ${pc(c.wrong_direction_rate)} | ${nc.n} / ${f(nc.exp)} / ${pc(nc.wd)} | ${inc ? `${f(I[inc].improvement_r)} / ${f(I[inc].wd_change)}` : '—'} |`; }; return [row('HTF BUY / 5m SELL (30m and 1H both oppose the signal)', 'A_HTF', 'HTF_CONFLICTING', 'C1 V6-HTF'), row('Cross-TF conflict (≤ 1 of 4 timeframes agree)', 'J_XTF', 'CONFLICT', 'C2 V6-AGREE'), row('Momentum / structure conflict (6-bar momentum opposes the signal)', 'E_MOM', 'OPPOSING', 'C3 V6-MOM'), row('Trend / range conflict (signal against the 5m trend regime)', 'D_REGIME', 'TREND_AGAINST', null), row('Volatility / geometry conflict (shock state)', 'L_SHOCK', 'SHOCK', null), row('News / setup conflict (within 60 min of a release)', 'I_NEWS', 'PRE_NEWS', null), row('Liquidity conflict (recent sweep against the signal)', 'H_SWEEP', 'AGAINST', null)]; }).join('\n')}\n\n## Reading\nConflicts are real as labels (6–16 % of signals each) but resolving them as WAIT reduces neither wrong-direction trades (changes of −1 to +1 point) nor losses in a way that persists: HTF and cross-TF conflicts are the LEAST negative states on HOLD; trend-against is positive on HOLD and negative on DEV; the only conflict that is negative on both splits is a recent sweep against the signal (−0.12 / −0.20 R), and the only one that lowers wrong-direction on both is shock — which is a safety WAIT, not a directional one. Forcing a direction was never attempted; WAIT was the only output. Measured effect on drawdown: C1 and C3 reduce HOLD DD from 98.9 R to 92.8 / 75.6 R by trading less, with expectancy still negative.\n`);
W('OPPORTUNITY_ELIGIBILITY.md', `# OPPORTUNITY ELIGIBILITY (DIRECTION VALID ≠ TRADE OPPORTUNITY VALID)\n\nIn V6 the direction layer only ever adds WAIT to an existing production (or V4 S3) setup + trigger; it never creates an entry. The table shows how much of the frozen opportunity stream each layer keeps and what the kept stream does on HOLDOUT.\n\n| Layer | Signals kept (CONTROL HOLD) | WAIT share | Trades | Exp (R) | Wrong-direction | Capture of large moves | Events blocked by the layer |\n|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return `| ${k} | ${v.signals_kept} / ${v.signals_in} | ${pc(v.wait_share)} | ${v.n} | ${f(v.expectancy_r)} | ${pc(v.wrong_direction_rate)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.blocked_events_share)} |`; }).join('\n')}\n\nSetup (frozen V4 families, SETUP_LAYER.md), trigger (frozen production/V4 triggers, TRIGGER_LAYER.md), location (ENTRY_LOCATION_GATE.md), geometry (TRADE_GEOMETRY_GATE.md) and risk/margin (RISK_MARGIN_GATE.md) remain required after direction. Reading: a BUY bias did not mean BUY immediately anywhere in V6, and the WAIT decisions it produced did not improve what was left.\n`);

// ---------- layers ----------
W('SETUP_LAYER.md', `# SETUP LAYER\n\nThe setup universe was NOT expanded. Setups come from the frozen streams: production MC / PB / BO / SR / MR (CONTROL) and the V4 first structure break (S3) as the best detector; the other V4 families (compression → expansion, sweep → reclaim, pullback → continuation, momentum ignition, range acceptance, trend resumption) were all negative or too rare in V4 and are not re-opened. V6 context layers were applied to both streams.\n\n${S2.map((S) => `## ${S} — S3 stream\n${candTable('S3', S)}\n`).join('\n')}\n## Reading\nOn the S3 stream the context layers behave as on CONTROL: nothing lowers wrong-direction materially, the location gate is degenerate (the broken swing is behind price → every S3 entry is BAD → C4/C6 keep nothing), and only C5 (shock/news WAIT) is marginally positive on HOLD (+0.015 R, PF 1.02, CI through zero) after being flat on DEV. Setup quality is not the lever either.\n`);
W('TRIGGER_LAYER.md', `# TRIGGER LAYER\n\nTriggers are frozen: production model triggers (confirmed close beyond the prior swing, resolved pullback, retest + reclaim, rejection wick, sweep + reclaim) for CONTROL, and the first confirmed close beyond a 3/3 swing for S3. Every trigger is observable on the confirmed decision candle (V4 TRIGGER_TIMING.md: triggers fire 1–3 ATR after the move origin by construction). V6 did not alter triggers; it asked whether context at the trigger bar predicts direction. Answer (WRONG_DIRECTION_ANALYSIS.md): the wrong-direction rate is ${pc(HC.wrong_direction_rate)} on HOLD for CONTROL and 27–34 % in every context state of every family — the trigger's direction error is not explained by any contemporaneous context tested.\n`);
W('ENTRY_LOCATION_GATE.md', `# ENTRY LOCATION GATE (SL distance, ATR displacement, distance to opposing structure, distance to objective, position in local range — pre-entry; WAIT if poor)\n\n${S2.map((S) => { const T = R[S].tables.CONTROL.families; return `## ${S} (CONTROL)\n| Measure | States: N / exp (R) / wrong-direction |\n|---|---|\n| Distance to opposing structure ÷ risk (GOOD ≥ 1.7 / NEUTRAL / BAD < 1.0) | ${Object.entries(T.G_LOCATION).map(([k, v]) => `${k} ${v.n} / ${f(v.expectancy_r)} / ${pc(v.wrong_direction_rate)}`).join('; ')} |\n| Position in the 24-bar range (toward the trade side) | ${Object.entries(T.F_RANGE_POS).map(([k, v]) => `${k} ${v.n} / ${f(v.expectancy_r)} / ${pc(v.wrong_direction_rate)}`).join('; ')} |\n| Range flags | ${Object.entries(T.F2_RANGE_FLAGS).map(([k, v]) => `${k} ${v.n} / ${f(v.expectancy_r)} / ${pc(v.wrong_direction_rate)}`).join('; ')} |\n`; }).join('\n')}\nSL distance in ATR and displacement from the origin were analysed in V5 (STRUCTURAL_STOP_ANALYSIS, ENTRY_LOCATION_ANALYSIS): wider stops lose less, displacement classes have identical target reach. Reading: the only pre-entry geometry that separates outcomes (opposing-structure distance) does so in the WRONG direction for a gate; "poor geometry → WAIT" (C4) waits on 83 % of entries and makes the remainder worse. RR was never lowered to force an entry. The gate is not adopted.\n`);
W('TRADE_GEOMETRY_GATE.md', `# TRADE GEOMETRY GATE (V5 findings applied; RR 1.70 feasibility classification, not RR change)\n\n| Population | Split | Trades (control exit) | Risk / ATR median | Reach +1 R before invalidation | Reach +1.7 R | Structural stop reached | Open-path MFE mean (R) | MAE mean (R) | Give-back (R) |\n|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => POPS.map((pop) => { const v = R[S].candidates[pop].CONTROL; return `| ${pop} | ${S} | ${v.n} | ${f(v.risk_usd_mean, 2)} USD | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.stop_reach)} | ${f(v.mfe_open_r, 2)} | ${f(v.mae_r, 2)} | ${f(v.giveback_r, 2)} |`; })).join('\n')}\n\nA 1.70 R objective is reached before invalidation in ${pc(HC.reach_1_7r)} of CONTROL HOLD trades, below the ≈ 47 % break-even reach (V5 RR_GEOMETRY). Under V6 the geometry gate is a classification only: trades whose 1.70 R objective is structurally obstructed are INELIGIBLE (the G-location BAD state), and the data show that this class is NOT the loss-maker. RR was not changed; the control is preserved. Finalist cross-check: ENTRY_ECONOMICS_CROSSCHECK.md.\n`);
W('RISK_MARGIN_GATE.md', `# RISK / MARGIN GATE (percentage / structure governed; no fixed-dollar loss, no martingale, no averaging, no revenge sizing)\n\n0.01 lot, Exness XAUUSDm, leverage 1:200 → margin ≈ price × 100 × 0.01 / 200 ≈ ${f(HC.capital.margin_usd_approx, 2)} USD; broker fail-safe risk per trade = 1.5 × structural + spread ≈ ${f(HC.capital.mean_broker_sl_usd, 2)} USD (CONTROL HOLD mean).\n\n| Capital | Risk % per trade (broker SL) | Margin % | HOLDOUT max DD % (CONTROL) | HOLDOUT max DD % (best V6, ${BEST}) | 0.01-lot feasibility |\n|---|---|---|---|---|---|\n${['62', '100', '1000', '10000'].map((cap) => { const a = HC.capital.by_capital[cap], b = HB.capital.by_capital[cap]; return `| $${cap} | ${pc(a.risk_pct)} | ${pc(a.margin_pct)} | ${pc(a.max_dd_pct)} | ${pc(b.max_dd_pct)} | ${a.feasible_001_lot} |`; }).join('\n')}\n\nThe $62 REAL account cannot support safe execution of one 0.01 lot (production MARGIN_SAFETY_VETO needs ≈ 71 USD equity): NO TRADE, reported, not worked around. No research conclusion was altered for it. Risk per trade at $10,000 is 0.1–0.2 % of capital; the HOLDOUT drawdown of the control is ${f(HC.max_dd_usd, 0)} USD.\n`);

// ---------- incremental / redundancy / ablation ----------
W('INFORMATION_INCREMENTAL_VALUE.md', `# INFORMATION INCREMENTAL VALUE (CONTROL vs CONTROL + FAMILY as a WAIT filter; sequential one-position; control exit; NORMAL costs; incremental = N ≥ 200, ≥ +0.05 R and lower wrong-direction)\n\n${INCH}\n${S2.flatMap((S) => POPS.flatMap((pop) => Object.entries(R.incremental[S][pop]).map(([k, v]) => incRow(S, pop, k, v)))).join('\n')}\n\n## DEV-derived state sets (rule: N ≥ 150, expectancy above base, wrong-direction below base)\n| Family | Supported | States kept |\n|---|---|---|\n${Object.entries(DEFN.state_sets).map(([k, v]) => `| ${k} | ${v.supported ? 'yes' : 'no'} | ${v.states.join(', ') || '—'} |`).join('\n')}\n\nFamilies with incremental value on both splits: ${DEC.families_with_incremental_value_both_splits.length ? DEC.families_with_incremental_value_both_splits.join(', ') : 'NONE'}; on one split: ${DEC.families_with_incremental_value_one_split.length ? DEC.families_with_incremental_value_one_split.join(', ') : 'NONE'}. INFORMATION_INCREMENTAL_VALUE = ${DEC.information_incremental_value}.\n\n## Reading\nNo fixed rule and no family adds ≥ 0.05 R with lower wrong-direction on either split. The largest HOLD improvement (C3 momentum, +0.031 R) came with slightly HIGHER wrong-direction and was −0.009 R on DEV. Every DEV-derived state set that looked useful on DEV (overlap window, US data window, high volatility, post-break, FULL agreement, SHOCK, BAD location) either reversed or shrank to noise on HOLD; the 15 "supported" sets intersect to an empty population (V6-COMPOSITE n = 0 on both splits), which is the pre-registered outcome of applying many weak, mutually inconsistent filters.\n`);
W('INFORMATION_REDUNDANCY.md', `# INFORMATION REDUNDANCY (pairwise phi between binary "supportive" flags on CONTROL signals; |phi| ≥ 0.5 = REDUNDANT)\n\n${S2.map((S) => { const rd = R[S].redundancy.CONTROL; return `## ${S}\nSupport rates: ${Object.entries(rd.support_rates).map(([k, v]) => `${k} ${pc(v)}`).join('; ')}.\n\n| Pair | phi |\n|---|---|\n${Object.entries(rd.phi).filter(([, v]) => v != null && Math.abs(v) >= 0.15).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1])).map(([k, v]) => `| ${k} | ${f(v, 2)} |`).join('\n')}\n\nRedundant pairs (|phi| ≥ 0.5): ${rd.redundant_pairs.length ? rd.redundant_pairs.join('; ') : 'none'}.\n`; }).join('\n')}\n## Reading\nThe families are largely independent (no |phi| ≥ 0.5): HTF structure and cross-TF agreement share 0.29; momentum and location −0.47 (supportive momentum tends to come with BAD location, i.e. the signal fires after the move has run toward the opposing swing); regime and shock 0.27. Correlation with past winners was not used to select features, and no redundant feature was added. The problem is not redundancy but absence of information: independent families each carry nothing about direction.\n`);
W('ABLATION_RESULTS.md', `# ABLATION RESULTS (best candidate ${R.ablation.best}; remove one information component at a time)\n\n${R.ablation.components.length ? S2.map((S) => `## ${S}\n| Variant | Trades | Exp (R) | Wrong-direction | Capture | Δ exp vs full |\n|---|---|---|---|---|---|\n${Object.entries(R.ablation[S]).map(([k, v]) => `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${pc(v.wrong_direction_rate)} | ${pc(v.capture)} | ${f(v.delta_expectancy_vs_full)} |`).join('\n')}\n`).join('\n') : `The best candidate by HOLDOUT expectancy (${R.ablation.best}) is a single-family rule (momentum not opposing), so there is no component to remove; its "ablation" is CONTROL itself: HOLD ${f(HC.expectancy_r)} → ${f(HB.expectancy_r)} R, wrong-direction ${pc(HC.wrong_direction_rate)} → ${pc(HB.wrong_direction_rate)}, capture ${pc(HC.move_capture.capture_rate)} → ${pc(HB.move_capture.capture_rate)}.`}\n\n## Classification of information\n| Family | Classification | Basis |\n|---|---|---|\n${Object.entries(R.incremental.HOLD.CONTROL).map(([k, v]) => { const d = R.incremental.DEV.CONTROL[k]; const cls = v.incremental && d.incremental ? 'CORE' : (v.improvement_r > 0 && d.improvement_r > 0) ? 'OPTIONAL (small, same sign)' : (v.improvement_r < -0.03 || d.improvement_r < -0.03) ? 'HARMFUL' : 'REDUNDANT / NEUTRAL'; return `| ${k} | ${cls} | DEV Δ ${f(d.improvement_r)} R, HOLD Δ ${f(v.improvement_r)} R; WD Δ ${f(d.wd_change)} / ${f(v.wd_change)} |`; }).join('\n')}\n\nNo information family is CORE. Location (C4) and the directional engine (C6) are HARMFUL; HTF, agreement and safety are NEUTRAL; momentum is OPTIONAL at best (+0.03 R on HOLD only).\n`);

// ---------- wrong direction / capture / economics ----------
W('WRONG_DIRECTION_ANALYSIS.md', `# WRONG-DIRECTION ANALYSIS (PRIMARY V6 METRIC)\n\nTwo measures: trade-level WRONG_DIRECTION (open-path MFE < 0.5 R and stopped) and event-level wrong direction (signal opposite to an objective ≥ 3 ATR move within ± 6 bars; V1–V4 definition).\n\n| Split | Population | Candidate | Trades | Trade-level WD | Event-level WD | Bad-entry | Right-direction (≥ +1 R) |\n|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => POPS.flatMap((pop) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates[pop][k]; return v.n ? `| ${S} | ${pop} | ${k} | ${v.n} | ${pc(v.wrong_direction_rate)} | ${pc(v.move_capture.wrong_direction_rate)} | ${pc(v.bad_entry_rate)} | ${pc(v.right_direction_rate)} |` : `| ${S} | ${pop} | ${k} | 0 | — | — | — | — |`; }))).join('\n')}\n\n## Wrong-direction rate by context state (CONTROL, HOLD; states with N ≥ 100)\n| Family | State | N | Wrong-direction | vs base ${pc(R.HOLD.tables.CONTROL.base.wrong_direction_rate)} |\n|---|---|---|---|---|\n${Object.entries(R.HOLD.tables.CONTROL.families).flatMap(([fam, st]) => Object.entries(st).filter(([, v]) => v.n >= 100).map(([k, v]) => `| ${fam} | ${k} | ${v.n} | ${pc(v.wrong_direction_rate)} | ${f(v.wrong_direction_rate - R.HOLD.tables.CONTROL.base.wrong_direction_rate)} |`)).join('\n')}\n\n## Reading\nThe wrong-direction rate of production entries is ${pc(HC.wrong_direction_rate)} (trade-level) / ${pc(HC.move_capture.wrong_direction_rate)} (event-level) on HOLD and it is ${pc(DC.wrong_direction_rate)} / ${pc(DC.move_capture.wrong_direction_rate)} on DEV. Across 18 context partitions and 60+ states with N ≥ 100, the trade-level rate stays within 25–34 %; the only states below 27 % on HOLD (US data window, trend-against regime, exhaustion, post-reclaim, range regime) were not below base on DEV, and none is a candidate. The best candidate (${BEST}) has wrong-direction ${pc(HB.wrong_direction_rate)} / ${pc(HB.move_capture.wrong_direction_rate)} vs CONTROL ${pc(HC.wrong_direction_rate)} / ${pc(HC.move_capture.wrong_direction_rate)}. DIRECTIONAL_ACCURACY_IMPROVED = ${DEC.directional_accuracy_improved}. Directional information has not solved the core problem: roughly 30 % of entries are wrong at the moment they are taken, whatever the HTF, session, volatility, regime, momentum, range, location, liquidity, news, agreement, activity or shock context says.\n`);
W('MOVE_CAPTURE_COMPARISON.md', `# MOVE CAPTURE COMPARISON (V4 move-event definition; events DEV ${R.meta.events.DEV} / HOLD ${R.meta.events.HOLD}; BLOCKED = events the unfiltered stream would have captured but the V6 layer waited out)\n\n| Split | Population | Candidate | Capture | Valid (≤ onset) | Late | Wrong direction | Already positioned | No signal | of which no setup/trigger | of which production gate | Blocked by V6 layer |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => POPS.flatMap((pop) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates[pop][k]; const m = v.move_capture; return `| ${S} | ${pop} | ${k} | ${pc(m.capture_rate)} | ${pc(m.valid_entry_rate)} | ${pc(m.late_entry_rate)} | ${pc(m.wrong_direction_rate)} | ${pc(m.already_positioned_rate)} | ${pc(m.no_signal_rate)} | ${pc(m.no_setup_or_trigger_rate)} | ${pc(m.gate_or_filter_rate)} | ${pc(v.blocked_events_share)} |`; }))).join('\n')}\n\n## Reading\nEvery V6 layer reduces capture (CONTROL ${pc(HC.move_capture.capture_rate)} → ${pc(HB.move_capture.capture_rate)} for ${BEST}; ${pc(R.HOLD.candidates.CONTROL['C4 V6-LOC'].move_capture.capture_rate)} for the location gate; ${pc(R.HOLD.candidates.CONTROL['C6 V6-DIR'].move_capture.capture_rate)} for the directional engine) and reduces event-level wrong direction by at most 2 points at the same time — the layers remove right and wrong trades in the same proportion. NO_SETUP / NO_TRIGGER is unchanged by construction (the layers sit after the trigger). A V6 engine that "reduces wrong direction AND reduces missed opportunities without negative expectancy" was not found; each layer moves only the trade count.\n`);
W('ENTRY_ECONOMICS_CROSSCHECK.md', `# ENTRY ECONOMICS CROSS-CHECK (V5 measures on the V6 finalists, HOLDOUT, control exit)\n\n| Candidate | Trades | Exp (R) | Reach +1 R | Reach +1.7 R | Stop reached | Open-path MFE (R) | MAE (R) | Give-back (R) | Win | Avg win / loss (R) | Risk USD mean |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${pc(v.reach_1r)} | ${pc(v.reach_1_7r)} | ${pc(v.stop_reach)} | ${f(v.mfe_open_r, 2)} | ${f(v.mae_r, 2)} | ${f(v.giveback_r, 2)} | ${pc(v.win_rate)} | ${f(v.avg_win_r, 2)} / ${f(v.avg_loss_r, 2)} | ${f(v.risk_usd_mean, 2)} |` : `| ${k} | 0 | — | — | — | — | — | — | — | — | — | — |`; }).join('\n')}\n\n## Reading\nTarget reach, stop reach, MFE, MAE and give-back of every V6-filtered population are within one or two points of CONTROL's (reach +1 R ${pc(HC.reach_1r)} → ${pc(HB.reach_1r)}; stop reach ${pc(HC.stop_reach)} → ${pc(HB.stop_reach)}). Context filtering did not change the trade economics of the kept trades, because it did not change their direction accuracy (WRONG_DIRECTION_ANALYSIS.md). ENTRY_ECONOMICS_IMPROVED = ${DEC.entry_economics_improved} (${BEST} point estimate ${f(HB.expectancy_r)} vs ${f(HC.expectancy_r)} R; CI ${ci(HB.ci95_r)} includes CONTROL).\n`);

// ---------- candidates / results ----------
W('CANDIDATE_DEFINITIONS.md', `# CANDIDATE DEFINITIONS (≤ 8; frozen in V6_PREREGISTRATION.md §7; every candidate = CONTROL entries + a WAIT layer; control exit; RR 1.70; lot 0.01)\n\n| Candidate | Hypothesis | Information sources | Direction rule (WAIT when…) | Setup / trigger / geometry / risk | Reason for inclusion |\n|---|---|---|---|---|---|\n| C1 V6-HTF | HTF agreement reduces wrong-direction trades | 30m + 1H structure | both oppose the signal | frozen production | V1 1H veto, V4 HTF context |\n| C2 V6-AGREE | multi-TF agreement improves direction | 5m, 15m, 30m, 1H structure | < 2 of 4 agree | frozen production | cross-TF hypothesis |\n| C3 V6-MOM | momentum against the signal predicts failure | 6-bar momentum / ATR | opposing (≥ 0.3 ATR against) | frozen production | V4 pre-move research (contrarian drift) |\n| C4 V6-LOC | target obstruction predicts failure | opposing 3/3 swing distance ÷ risk | BAD (< 1.0 × risk) | frozen production | V5 location terciles |\n| C5 V6-SAFETY | abnormal conditions should block | shock (3 ATR bar / ATR ratio ≥ 1.5 / abnormal spread) + ±60 min official release | shock or pre/post news | frozen production | safety hypothesis (L, I) |\n| C6 V6-DIR | explicit evidence relations authorise a direction | 30m/1H structure + momentum + location | no HTF support, any HTF opposition, opposing momentum or BAD location | frozen production | directional bias engine hypothesis |\n| C7 V6-SIMPLE | the smallest independently useful set | DEV-selected fixed rules: ${DEFN.simple.join(' ∩ ')} (${DEFN.simple_note}) | union of the component WAITs | frozen production | simplicity baseline |\n| C8 V6-COMPOSITE | all DEV-supported state sets together | ${Object.entries(DEFN.state_sets).filter(([, v]) => v.supported).map(([k]) => k).join(', ')} | any family outside its DEV-kept states | frozen production | composite baseline |\n\nNo arbitrary confidence score was used anywhere.\n`);
W('FROZEN_FINALISTS.md', `# FROZEN FINALISTS\n\n\`configs/finalists.json\` sha256 **${R.finalists_sha256}**, derived from DEV only (results/dev_phase_console.txt), frozen before HOLDOUT was opened (results/full_phase_console.txt). Contents: the DEV-derived state sets per family, the DEV incremental-value evaluation of the fixed rules, and the V6-SIMPLE composition.\n\n| Fixed rule | DEV trades | DEV Δ exp (R) | WD lower on DEV | Incremental (N ≥ 200, ≥ +0.05 R, lower WD) |\n|---|---|---|---|---|\n${DEFN.fixed_rule_dev_value.map((x) => `| ${x.k} | ${x.dev_n} | ${f(x.improvement_r)} | ${x.wd_lower ? 'yes' : 'no'} | ${x.incremental ? 'YES' : 'no'} |`).join('\n')}\n\nV6-SIMPLE = ${DEFN.simple.join(' ∩ ')} — ${DEFN.simple_note}. V6-COMPOSITE = intersection of ${Object.values(DEFN.state_sets).filter((v) => v.supported).length} DEV-supported state sets (listed in INFORMATION_INCREMENTAL_VALUE.md). No fixed rule had DEV incremental value, so the pre-registration's fallback (single best fixed rule) applied.\n`);
W('DEVELOPMENT_RESULTS.md', `# DEVELOPMENT RESULTS (2025-05-07 → 2025-12-31; sequential; control exit; NORMAL costs)\n\n## CONTROL stream\n${candTable('CONTROL', 'DEV')}\n\n## S3 stream\n${candTable('S3', 'DEV')}\n\nOn DEV no candidate improved expectancy by more than +0.001 R over CONTROL; C3 (momentum) lowered wrong-direction by 1.1 points at −0.009 R; C4 and C6 waited on 83–95 % of signals and lost more per trade. The DEV phase gave no reason to expect a HOLDOUT edge; all eight candidates were carried forward once as pre-registered.\n`);
W('HOLDOUT_RESULTS.md', `# HOLDOUT RESULTS (2026-01-01 → 2026-09-29; opened once after configs/finalists.json was hashed; sequential; control exit; NORMAL costs)\n\n## CONTROL stream\n${candTable('CONTROL', 'HOLD')}\n\n## S3 stream\n${candTable('S3', 'HOLD')}\n\n## Gate decisions (V6_PREREGISTRATION.md §9; CONTROL stream)\n| Candidate | Status | Failed items |\n|---|---|---|\n${CANDS.map((k) => `| ${k} | ${DEC.candidates[k].status} | ${(DEC.candidates[k].reasons ?? []).join('; ') || '—'} |`).join('\n')}\n\nPassing: ${DEC.passing.length ? DEC.passing.join(', ') : 'none'}. Best by HOLDOUT expectancy with N ≥ 200: **${BEST}** (${f(HB.expectancy_r)} R, PF ${f(HB.pf, 2)}, DD ${f(HB.max_dd_r, 1)} R, CI ${ci(HB.ci95_r)}, wrong-direction ${pc(HB.wrong_direction_rate)} vs ${pc(HC.wrong_direction_rate)}, capture ${pc(HB.move_capture.capture_rate)} vs ${pc(HC.move_capture.capture_rate)}). INFORMATION_INCREMENTAL_VALUE = ${DEC.information_incremental_value}; DIRECTIONAL_ACCURACY_IMPROVED = ${DEC.directional_accuracy_improved}; ENTRY_ECONOMICS_IMPROVED = ${DEC.entry_economics_improved}; EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; DEMO_ELIGIBLE = ${DEC.demo_eligible}.\n`);
W('NORMAL_COST_RESULTS.md', `# NORMAL COST RESULTS (spread 0.24 + slippage 0.10 USD; DRIFT = next-open fill; HOLDOUT, CONTROL stream)\n\n| Candidate | Trades | Exp (R) | Exp (USD @0.01) | Cost USD/trade | PF | DD (R) | Drift exp (R) | Drift PF |\n|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.cost_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${f(v.drift.expectancy_r)} | ${f(v.drift.pf, 2)} |` : `| ${k} | 0 | — | — | — | — | — | — | — |`; }).join('\n')}\n\nUSD at the frozen 0.01 lot is informational. Every candidate is negative at normal cost.\n`);
W('STRESS_COST_RESULTS.md', `# STRESS COST RESULTS (spread 0.60 + slippage 0.20 USD; HOLDOUT and DEV, CONTROL stream)\n\n| Split | Candidate | Trades | Normal exp (R) | Stress exp (R) | Stress PF | Degradation (R) |\n|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; return v.n ? `| ${S} | ${k} | ${v.stress.n} | ${f(v.expectancy_r)} | ${f(v.stress.expectancy_r)} | ${f(v.stress.pf, 2)} | ${f(v.stress.expectancy_r - v.expectancy_r)} |` : `| ${S} | ${k} | 0 | — | — | — | — |`; })).join('\n')}\n\nNo candidate is positive before costs, so none can be rescued by cost assumptions; stress costs remove a further 0.08–0.10 R per trade.\n`);
W('WALK_FORWARD_RESULTS.md', `# WALK-FORWARD RESULTS (calendar quarters; sequential; control exit; CONTROL stream)\n\n${S2.map((S) => `## ${S}\n| Candidate | ${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).join(' | ')} | Quarters > 0 |\n|---|${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).map(() => '---|').join('')}---|\n${['CONTROL', ...CANDS].map((k) => { const v = R[S].candidates.CONTROL[k]; if (!v.n) return `| ${k} | ${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).map(() => '—').join(' | ')} | — |`; return `| ${k} | ${Object.keys(R[S].candidates.CONTROL.CONTROL.walk_forward).map((q) => { const x = v.walk_forward[q]; return x ? `n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}, DD ${f(x.max_dd_r, 0)}, WD ${pc(x.wrong_direction_rate)}, ${f(x.trades_per_session, 1)}/session` : '—'; }).join(' | ')} | ${pc(v.quarters_positive_share)} |`; }).join('\n')}\n`).join('\n')}\n## Reading\nEvery candidate's quarterly sign pattern is CONTROL's (negative, positive, negative on HOLD): the layers scale the stream, they do not change its path. Wrong-direction is 27–34 % in every quarter for every candidate. Nothing is period-robust.\n`);
W('PARAMETER_STABILITY.md', `# PARAMETER STABILITY (pre-registered neighbours; HOLDOUT; CONTROL stream)\n\n${CANDS.map((k) => { const nb = R.neighbourhoods[k]; return `## ${k} — ${nb.classification}\n| Variant | Trades | Exp (R) | PF | Wrong-direction |\n|---|---|---|---|---|\n${Object.entries(nb).filter(([a]) => a !== 'classification').map(([a, v]) => `| ${a} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${pc(v.wrong_direction_rate)} |`).join('\n')}\n`; }).join('\n')}\n## Reading\nEvery candidate is NEGATIVE_CENTRE: the neighbourhoods are flat and negative (momentum 0.2 / 0.3 / 0.5 ATR: −0.032 / −0.033 / −0.034 R; agreement 1 / 2 / 3: −0.063 / −0.050 / −0.078 R; news 30 / 60 / 90 min and shock 2.5 / 3 / 3.5 ATR within 0.01 R). The location gate's neighbours are identical because the pre-registered neighbours (1.5 / 2.0) move the GOOD/NEUTRAL boundary while the WAIT acts on the fixed BAD boundary (1.0) — a limitation of the pre-registration, reported. There are no needle peaks because there are no peaks.\n`);
W('UNCERTAINTY_ANALYSIS.md', `# UNCERTAINTY ANALYSIS (trade bootstrap 2,000 draws seed 20260930; session-block bootstrap seed 7; month-shuffle adverse sequencing 500 draws; HOLDOUT, CONTROL stream)\n\n| Candidate | N | Exp (R) | Trade 95 % CI | Trade 99 % CI | Block 95 % CI | Block 99 % CI | PF | Max loss streak | Adverse DD R p50 / p90 / p99 | Adverse loss streak p50 / p90 |\n|---|---|---|---|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = R.HOLD.candidates.CONTROL[k]; return v.n ? `| ${k} | ${v.n} | ${f(v.expectancy_r)} | ${ci(v.ci95_r)} | ${ci(v.ci99_r)} | ${ci(v.block_ci95_r)} | ${ci(v.block_ci99_r)} | ${f(v.pf, 2)} | ${v.max_loss_streak} | ${v.adverse ? `${f(v.adverse.dd_r_p50, 1)} / ${f(v.adverse.dd_r_p90, 1)} / ${f(v.adverse.dd_r_p99, 1)}` : '—'} | ${v.adverse ? `${v.adverse.loss_streak_p50} / ${v.adverse.loss_streak_p90}` : '—'} |` : `| ${k} | 0 | — | — | — | — | — | — | — | — | — |`; }).join('\n')}\n\n## Reading\nEvery CI includes zero and every point estimate is negative; the best candidate's 95 % CI is ${ci(HB.ci95_r)}. EDGE = NO (not INCONCLUSIVE: INCONCLUSIVE requires a positive point estimate with lower wrong-direction, and no candidate has either).\n`);
W('V6_SIMPLE_VS_COMPOSITE.md', `# V6-SIMPLE vs V6-COMPOSITE\n\n| | V6-SIMPLE | V6-COMPOSITE |\n|---|---|---|\n| Definition | ${DEFN.simple.join(' ∩ ')} (${DEFN.simple_note}) | intersection of ${Object.values(DEFN.state_sets).filter((v) => v.supported).length} DEV-supported state sets |\n| DEV trades / exp / WD | ${DEC.simple_vs_composite.simple.dev.n} / ${f(DEC.simple_vs_composite.simple.dev.expectancy_r)} / ${pc(DEC.simple_vs_composite.simple.dev.wrong_direction_rate)} | ${DEC.simple_vs_composite.composite.dev.n} / — / — |\n| HOLD trades / exp / PF / DD | ${DEC.simple_vs_composite.simple.hold.n} / ${f(DEC.simple_vs_composite.simple.hold.expectancy_r)} / ${f(DEC.simple_vs_composite.simple.hold.pf, 2)} / ${f(DEC.simple_vs_composite.simple.hold.max_dd_r, 1)} | ${DEC.simple_vs_composite.composite.hold.n} / — / — / — |\n| HOLD wrong-direction (trade / events) | ${pc(DEC.simple_vs_composite.simple.hold.wrong_direction_rate)} / ${pc(DEC.simple_vs_composite.simple.hold.event_wd)} | — |\n| HOLD capture | ${pc(DEC.simple_vs_composite.simple.hold.capture)} | 0 |\n| WAIT share | ${pc(DEC.simple_vs_composite.simple.hold.wait_share)} | 100 % |\n\nSimple beats complex trivially: the composite of every individually "useful" DEV state waits on 100 % of signals on both splits, which is what stacking many weak, DEV-fitted filters produces. The simple rule (cross-TF agreement ≥ 2) is ≈ CONTROL (−0.050 vs −0.064 R, wrong-direction unchanged). Neither is an engine.\n`);
W('CONTROL_VS_V6.md', `# CONTROL vs V6 (HOLDOUT, sequential, control exit, NORMAL costs)\n\n| Metric | CONTROL | ${BEST} (best V6) | V6-SIMPLE | V6-DIR (directional engine) |\n|---|---|---|---|---|\n${[['Trades', (v) => v.n], ['WAIT share', (v) => pc(v.wait_share)], ['Expectancy (R)', (v) => f(v.expectancy_r)], ['PF', (v) => f(v.pf, 2)], ['Max DD (R)', (v) => f(v.max_dd_r, 1)], ['Trade 95 % CI', (v) => ci(v.ci95_r)], ['Stress exp (R)', (v) => f(v.stress?.expectancy_r)], ['Wrong-direction (trade)', (v) => pc(v.wrong_direction_rate)], ['Wrong-direction (events)', (v) => pc(v.move_capture?.wrong_direction_rate)], ['Bad-entry', (v) => pc(v.bad_entry_rate)], ['Move capture', (v) => pc(v.move_capture?.capture_rate)], ['Quarters > 0', (v) => pc(v.quarters_positive_share)], ['Win rate', (v) => pc(v.win_rate)]].map(([k, g]) => `| ${k} | ${g(HC)} | ${g(HB)} | ${g(R.HOLD.candidates.CONTROL['C7 V6-SIMPLE'])} | ${g(R.HOLD.candidates.CONTROL['C6 V6-DIR'])} |`).join('\n')}\n| DEV exp (R) | ${f(DC.expectancy_r)} | ${f(R.DEV.candidates.CONTROL[BEST].expectancy_r)} | ${f(R.DEV.candidates.CONTROL['C7 V6-SIMPLE'].expectancy_r)} | ${f(R.DEV.candidates.CONTROL['C6 V6-DIR'].expectancy_r)} |\n\nCONTROL vs V6: the best layer is a smaller sample of the same stream with the same direction error. Information quality, as far as the twelve families available in this environment can express it, is not the missing ingredient.\n`);
W('INFORMATION_EDGE_V6_SPEC.md', `# INFORMATION EDGE V6 — IMPLEMENTATION SPEC (NOT IMPLEMENTED: no candidate passed; kept so a future passing context layer can be ported deterministically)\n\n1. Position in the pipeline: MARKET CONTEXT → DIRECTIONAL BIAS → ELIGIBILITY sit AFTER the production signal (setup + trigger + production gates) and BEFORE the executor; the layer may only emit WAIT (never a direction, never an entry).\n2. Inputs at the confirmed 5m close: confirmed bars (≥ 400), the production 15m/30m/1H/4H regime/structure/bias labels the watcher already fetches, the News V2 calendar's scheduled release times, MT5 tick volume and spread of the confirmed bar.\n3. Context vector = the 18 pre-registered partitions (V6_PREREGISTRATION.md §5), computed by pure functions of (1)–(2); the directional layer = explicit evidence relations (no score); the conflict layer = WAIT; all thresholds frozen.\n4. Decision log per candle: context vector, eligible direction, conflict reason, WAIT/PASS — for parity fixtures and the 5-day demo observation.\n5. Safety unchanged: News V2, spread, drift, breakers, identity, dedup, one position, MARGIN_SAFETY_VETO, broker SL 1.5×; RR 1.70; lot 0.01; Capital Harvest OFF.\n6. Parity fixtures before wiring: ≥ 200 live candles → identical context labels and WAIT decisions versus replay; the live 30m structure null-handling, the release-time source and the broker's tick-volume/spread feed fixtured explicitly.\n7. Rollback: single mode flag, OFF by default, unwired module; no registry file touched.\n\nStatus: SPEC ONLY. EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; nothing was wired.\n`);
